package de.feldexa.app.storage

import java.io.ByteArrayOutputStream
import java.nio.ByteBuffer
import java.nio.ByteOrder
import java.util.Base64
import java.util.zip.CRC32
import java.util.zip.Deflater

/**
 * Test-only synthetic PNG factory.
 *
 * Ordinary fixtures are built by this small encoder (filter 0, RGBA8) and
 * additionally anchored by two hard-coded PNGs generated by an independent
 * Python zlib/CRC implementation. The chunk builder exists only to construct
 * adversarial streams (wrong filter, interlaced row layout, decompression
 * bomb) that are still syntactically PNG.
 */
internal object TestPng {

    fun validRgba(
        width: Int,
        height: Int,
        argb: Int = 0xFF336699.toInt(),
    ): ByteArray {
        val rowBytes = width * 4
        val raw = ByteArray((rowBytes + 1) * height)
        val red = (argb ushr 16) and 0xFF
        val green = (argb ushr 8) and 0xFF
        val blue = argb and 0xFF
        val alpha = (argb ushr 24) and 0xFF
        var cursor = 0
        repeat(height) {
            raw[cursor++] = 0 // filter: none
            repeat(width) {
                raw[cursor++] = red.toByte()
                raw[cursor++] = green.toByte()
                raw[cursor++] = blue.toByte()
                raw[cursor++] = alpha.toByte()
            }
        }
        return fromRawScanlines(
            width = width,
            height = height,
            colorType = 6,
            bitDepth = 8,
            interlace = 0,
            rawScanlines = raw,
        )
    }

    /** Independently generated 2×2 RGBA PNG (Python zlib + CRC32). */
    fun independent2x2(): ByteArray = Base64.getDecoder().decode(INDEPENDENT_2X2)

    /** Independently generated 1024×1 RGBA PNG (Python zlib + CRC32). */
    fun independent1024(): ByteArray = Base64.getDecoder().decode(INDEPENDENT_1024)

    /** Reads width × height from the IHDR of a structurally valid fixture. */
    fun size(png: ByteArray): Pair<Int, Int> {
        var offset = 8
        while (offset + 12 <= png.size) {
            val length = ByteBuffer.wrap(png, offset, 4).order(ByteOrder.BIG_ENDIAN).int
            val type = String(png, offset + 4, 4, Charsets.US_ASCII)
            val dataStart = offset + 8
            if (type == "IHDR") {
                val buffer = ByteBuffer.wrap(png, dataStart, length)
                    .order(ByteOrder.BIG_ENDIAN)
                return buffer.int to buffer.int
            }
            offset = dataStart + length + 4
        }
        error("IHDR not found")
    }

    /**
     * Builds a non-interlaced or Adam7-interlaced PNG from already-filtered
     * raw scanlines. The caller owns the row layout; the resulting bytes are
     * a real PNG. Optional chunks can be placed before the first IDAT (for
     * `PLTE`/`tRNS`) or between IDAT and IEND (for ordering negatives).
     */
    fun fromRawScanlines(
        width: Int,
        height: Int,
        colorType: Int,
        bitDepth: Int,
        interlace: Int,
        rawScanlines: ByteArray,
        beforeIdat: List<ByteArray> = emptyList(),
        afterIdat: List<ByteArray> = emptyList(),
    ): ByteArray {
        val ihdr = ByteBuffer.allocate(13).order(ByteOrder.BIG_ENDIAN).apply {
            putInt(width)
            putInt(height)
            put(bitDepth.toByte())
            put(colorType.toByte())
            put(0)
            put(0)
            put(interlace.toByte())
        }.array()
        val chunks = buildList {
            add(chunk("IHDR", ihdr))
            addAll(beforeIdat)
            add(chunk("IDAT", deflate(rawScanlines)))
            addAll(afterIdat)
            add(chunk("IEND", ByteArray(0)))
        }
        return assemble(chunks)
    }

    /** RGB8 with no alpha channel and no tRNS (opaque, §2.4-rejected). */
    fun validRgb(
        width: Int,
        height: Int,
        red: Int = 0x11,
        green: Int = 0x22,
        blue: Int = 0x33,
    ): ByteArray {
        val raw = ByteArray((width * 3 + 1) * height)
        var cursor = 0
        repeat(height) {
            raw[cursor++] = 0
            repeat(width) {
                raw[cursor++] = red.toByte()
                raw[cursor++] = green.toByte()
                raw[cursor++] = blue.toByte()
            }
        }
        return fromRawScanlines(width, height, colorType = 2, bitDepth = 8, interlace = 0, raw)
    }

    /** Grayscale with no alpha channel and no tRNS (opaque, §2.4-rejected). */
    fun validGrayscale(width: Int, height: Int, gray: Int = 0x80): ByteArray {
        val raw = ByteArray((width + 1) * height)
        var cursor = 0
        repeat(height) {
            raw[cursor++] = 0
            repeat(width) { raw[cursor++] = gray.toByte() }
        }
        return fromRawScanlines(width, height, colorType = 0, bitDepth = 8, interlace = 0, raw)
    }

    /** Grayscale+alpha 8-bit (native alpha type 4). */
    fun validGrayscaleAlpha(
        width: Int,
        height: Int,
        gray: Int = 0x80,
        alpha: Int = 0xFF,
    ): ByteArray {
        val raw = ByteArray((width * 2 + 1) * height)
        var cursor = 0
        repeat(height) {
            raw[cursor++] = 0
            repeat(width) {
                raw[cursor++] = gray.toByte()
                raw[cursor++] = alpha.toByte()
            }
        }
        return fromRawScanlines(width, height, colorType = 4, bitDepth = 8, interlace = 0, raw)
    }

    /** Indexed8 with a two-entry palette but no tRNS (opaque, §2.4-rejected). */
    fun validIndexed(width: Int, height: Int): ByteArray {
        val raw = ByteArray((width + 1) * height)
        var cursor = 0
        repeat(height) {
            raw[cursor++] = 0
            repeat(width) { raw[cursor++] = 0 }
        }
        return fromRawScanlines(
            width = width,
            height = height,
            colorType = 3,
            bitDepth = 8,
            interlace = 0,
            rawScanlines = raw,
            beforeIdat = listOf(chunk("PLTE", INDEXED_PALETTE)),
        )
    }

    /** Inserts [newChunk] immediately before the first chunk of [type]. */
    fun insertBeforeChunk(png: ByteArray, type: String, newChunk: ByteArray): ByteArray {
        var offset = MAGIC.size
        while (offset + 12 <= png.size) {
            val length = ByteBuffer.wrap(png, offset, 4).order(ByteOrder.BIG_ENDIAN).int
            val chunkType = String(png, offset + 4, 4, Charsets.US_ASCII)
            val dataEnd = offset + 8 + length
            if (dataEnd + 4 > png.size) break
            if (chunkType == type) {
                val out = ByteArrayOutputStream()
                out.write(png, 0, offset)
                out.write(newChunk)
                out.write(png, offset, png.size - offset)
                return out.toByteArray()
            }
            offset = dataEnd + 4
        }
        error("chunk $type not found")
    }

    /** Inserts [newChunk] immediately before the first IDAT. */
    fun insertBeforeIdat(png: ByteArray, newChunk: ByteArray): ByteArray =
        insertBeforeChunk(png, "IDAT", newChunk)

    fun assemble(chunks: List<ByteArray>): ByteArray {
        val out = ByteArrayOutputStream()
        out.write(MAGIC)
        for (chunk in chunks) out.write(chunk)
        return out.toByteArray()
    }

    fun chunk(type: String, data: ByteArray): ByteArray {
        require(type.length == 4) { "chunk type must be four ASCII letters" }
        val typeBytes = type.toByteArray(Charsets.US_ASCII)
        val out = ByteArrayOutputStream()
        out.write(
            ByteBuffer.allocate(4).order(ByteOrder.BIG_ENDIAN)
                .putInt(data.size).array(),
        )
        out.write(typeBytes)
        out.write(data)
        val crc = CRC32()
        crc.update(typeBytes)
        crc.update(data)
        out.write(
            ByteBuffer.allocate(4).order(ByteOrder.BIG_ENDIAN)
                .putInt(crc.value.toInt()).array(),
        )
        return out.toByteArray()
    }

    fun deflate(bytes: ByteArray): ByteArray {
        val deflater = Deflater()
        try {
            deflater.setInput(bytes)
            deflater.finish()
            val out = ByteArrayOutputStream()
            val buffer = ByteArray(4096)
            while (!deflater.finished()) {
                val count = deflater.deflate(buffer)
                out.write(buffer, 0, count)
            }
            return out.toByteArray()
        } finally {
            deflater.end()
        }
    }

    /** Replaces the first chunk data of [type] in a structurally valid PNG. */
    fun replaceFirstChunkData(
        png: ByteArray,
        type: String,
        transform: (ByteArray) -> ByteArray,
    ): ByteArray {
        var offset = MAGIC.size
        while (offset + 12 <= png.size) {
            val length = ByteBuffer.wrap(png, offset, 4).order(ByteOrder.BIG_ENDIAN).int
            val chunkType = String(png, offset + 4, 4, Charsets.US_ASCII)
            val dataStart = offset + 8
            val dataEnd = dataStart + length
            if (dataEnd + 4 > png.size) break
            if (chunkType == type) {
                val replacement = transform(png.copyOfRange(dataStart, dataEnd))
                val out = ByteArrayOutputStream()
                out.write(png, 0, offset)
                out.write(chunk(type, replacement))
                out.write(png, dataEnd + 4, png.size - (dataEnd + 4))
                return out.toByteArray()
            }
            offset = dataEnd + 4
        }
        error("chunk $type not found")
    }

    fun firstChunkData(png: ByteArray, type: String): ByteArray {
        var offset = MAGIC.size
        while (offset + 12 <= png.size) {
            val length = ByteBuffer.wrap(png, offset, 4).order(ByteOrder.BIG_ENDIAN).int
            val chunkType = String(png, offset + 4, 4, Charsets.US_ASCII)
            val dataStart = offset + 8
            if (chunkType == type) return png.copyOfRange(dataStart, dataStart + length)
            offset = dataStart + length + 4
        }
        error("chunk $type not found")
    }

    private const val INDEPENDENT_2X2 =
        "iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAYAAABytg0kAAAAEUlEQVR42mMwTpv5H4QZ" +
            "YAwAScgIxevRCIwAAAAASUVORK5CYII="
    private const val INDEPENDENT_1024 =
        "iVBORw0KGgoAAAANSUhEUgAABAAAAAABCAYAAABADtw1AAAAIUlEQVR42u3DAQ0AAAgD" +
            "IDvZyU5Pqz0cbFRPVlVVVf39AGAOxHn43lj+AAAAAElFTkSuQmCC"

    private val MAGIC = byteArrayOf(
        0x89.toByte(),
        0x50,
        0x4E,
        0x47,
        0x0D,
        0x0A,
        0x1A,
        0x0A,
    )

    val INDEXED_PALETTE: ByteArray = byteArrayOf(
        0xFF.toByte(), 0x00, 0x00,
        0x00, 0xFF.toByte(), 0x00,
    )
}
